    let mut used: i32 = 0;
    let mut q: i32 = q0;
    let mut q1: i32 = q0;
    let mut el: i32 = 0;
    let mut ao1: i32 = 0;
    let mut fleaf: i32 = -1;
    let mut sleaf: i32 = -1;
    let mut sl: i32 = -1;
    let mut s2: i32 = 0;
    let mut cx: i32 = 0;
    let mut unacc: i32 = 0;
