    if rs < 0 {
        return rs;
    }
    let m: i32 = finish_comb(p, pool, b, s, fb, w, nq, pos, q, ext);
    if m < 0 {
        return m;
    }
    if (m == 0) && (((ctx & CTX_KEY) == 0) && wit_empty(s)) {
        if unacc > 0 {
            wit_set(s, R_MISSING, 0, d, P_INDEX, el, pos);
        } else {
            let r1: i32 = rule1(s, fb, w, nq, d, pos);
            if r1 < 0 {
                return r1;
            }
        }
    }
